<script setup>
import MediaPreview from './MediaPreview.vue'
</script>

<template>
  <div class="flex flex-col gap-4 p-2 w-full max-w-2xl">
    <h3 class="font-bold text-lg flex items-center gap-2">
      <i class="fa-solid fa-cloud-arrow-up text-primary"></i>
